import urllib.request,json
for repo in ['biocontainers/anndata','biocontainers/scanpy-scripts','biocontainers/scanpy']:
 print('REPO',repo)
 try:
  for page in range(1,4):
   data=json.load(urllib.request.urlopen(f'https://quay.io/api/v1/repository/{repo}/tag/?limit=100&page={page}&onlyActiveTags=true',timeout=20))
   for t in data.get('tags',[])[:100]:
    name=t['name']
    if name.startswith(('0.8','0.9','0.10','0.11','1.9','1.10','1.11')):
     print(name)
 except Exception as e: print(e)
PY"

